-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"تمييز صورة الطبيعة في النص الشعري","passage":"تحليل «وقور على ظهر الفلاة» لابن خفاجة يقتضي الاطلاع على الأبيات الأصلية وتوثيقها، ولا يجوز اختلاق صور ونسبتها للشاعر. تدريب مستقل من ضاديوم: «بدا الجبل عند الغروب كأنه حارس صامت، والريح تمر بجوانبه». يساعد المثال على تحديد المشبّه والمشبّه به، ولا يمثل بيتًا من القصيدة.","prompt":"في التشبيه المستقل ما الشيء المشبه بالحارس؟","correct":"الجبل","w1":"الريح","w2":"الغروب","w3":"الطريق","practice":"استخرج من القصيدة الأصلية شاهدًا موثقًا على صورة للطبيعة، ثم قارنها بصورتك الشعرية المستقلة."},{"n":2,"skill":"أوزان الكلمات في الميزان الصرفي","passage":"وزن «كَتَبَ» هو «فَعَلَ» إذا قابلنا الحروف الأصلية بالفاء والعين واللام، ووزن «كاتِب» هو «فاعِل» لزيادة الألف. نميز الزوائد والحروف الأصلية بالاشتقاق، ولا نعتمد على عدد حروف الكلمة الظاهر وحده.","prompt":"ما وزن «كاتب»؟","correct":"فاعل","w1":"مفعول","w2":"فعّل","w3":"استفعل","practice":"زن سبع كلمات مشتقة مع بيان الحروف الأصلية وحروف الزيادة، وصحح وزن كلمة أخطأت فيه أول مرة."},{"n":3,"skill":"الجامد والمشتق في الدلالة","passage":"«كِتاب» اسم جامد بالمعنى التصنيفي المدرسي الشائع لاسم الذات، بينما «كاتِب» اسم فاعل مشتق من الفعل «كتب» للدلالة على من قام بالكتابة. ينبغي الانتباه إلى أن بعض الأسماء قد تُحلل تاريخيًا بطرق لغوية أوسع؛ نستخدم هنا التمييز المدرسي.","prompt":"أي كلمة اسم فاعل مشتق؟","correct":"كاتب","w1":"كتاب","w2":"قلم","w3":"باب","practice":"صنف عشر كلمات إلى جامد ومشتق في السياق المدرسي ثم بيّن الفعل الأصل في الأسماء المشتقة."},{"n":4,"skill":"تسلسل الأحداث في النص السردي","passage":"في قصة مستقلة أراد التلميذ إدراج لوحة في معرض المدرسة، لكن الصورة التي طبعها لم تكن واضحة؛ أصلحها بالتعاون مع زميله ثم قدمها في الموعد. يضم السرد حدثًا أول وعقبة وحلًا ونتيجة، ويصل بين المراحل بسبب وزمن واضحين.","prompt":"ما العقدة الأساسية في القصة؟","correct":"عدم وضوح الصورة المطبوعة","w1":"دخول المعرض","w2":"وجود زميل","w3":"عرض اللوحة بعد إصلاحها","practice":"اكتب قصة في عشرة أسطر لها شخصية وعقدة وحل، واستعمل رابطين زمنيين يوضحان تطور الأحداث."},{"n":5,"skill":"دراسة الغزل دون اختلاق الأبيات","passage":"لفهم «وهل يخفى القمر» لعمر بن أبي ربيعة يجب الرجوع إلى النص المقرر نفسه وتوثيق المتكلم والمخاطب وصور الغزل. مثال أصلي: «تضيء ابتسامتها المكان كما يضيء الصباح نافذة البيت». يتضمن تشبيهًا من إنشاء ضاديوم ولا يمثل شعر الشاعر.","prompt":"ما المشبّه به في المثال الأصلي؟","correct":"الصباح","w1":"ابتسامتها","w2":"البيت","w3":"المكان","practice":"من النص الأصلي استخرج تشبيهًا موثقًا وناقش وظيفته ثم اكتب تشبيهًا من عندك."},{"n":6,"skill":"المصدر واشتقاقه","passage":"«كتابة» مصدر للفعل «كتب» يدل على الحدث مجردًا من الزمن، و«قراءة» مصدر للفعل «قرأ»، بينما «كاتب» اسم فاعل لا مصدر. قد تختلف أوزان المصادر بحسب الفعل الثلاثي والسماعي والمزيد القياسي.","prompt":"أي كلمة مصدر للفعل «قرأ»؟","correct":"قراءة","w1":"قارئ","w2":"مقروء","w3":"يقرأ","practice":"اشتق مصادر ثمانية أفعال مع تحديد ما إذا كانت ثلاثية أو مزيدة، واستخدم ثلاثة مصادر في جمل."},{"n":7,"skill":"اسم الفاعل في الأمثلة","passage":"«الكاتبُ منشغلٌ» تتضمن اسم فاعل «الكاتب» من «كتب»، و«المجتهد» من «اجتهد» على وزن اسم الفاعل من غير الثلاثي. لا يُعد كل اسم يدل على شخص اسم فاعل مشتقًا بالقاعدة نفسها.","prompt":"ما اسم الفاعل من «كتب»؟","correct":"كاتب","w1":"مكتوب","w2":"كتاب","w3":"كتابة","practice":"اشتق أسماء فاعلين من خمسة أفعال ثلاثية وخمسة غير ثلاثية، ثم استعملها في جمل ذات معنى."},{"n":8,"skill":"الصفة المشبهة للدلالة على الثبوت النسبي","passage":"«كريم» من الفعل اللازم «كرُم» صفة مشبهة تدل غالبًا على صفة أكثر ثبوتًا في الاستعمال من اسم فاعل يدل على حدوث فعل، مثل «كاتب». وهذا فرق دلالي تقريبي لا يمنع تغير الصفات بحسب السياق.","prompt":"أي كلمة صفة مشبهة في المثال؟","correct":"كريم","w1":"كاتب","w2":"مكتوب","w3":"كتابة","practice":"اكتب خمس صفات مشبهة وأسماء فاعلين مقابلة بالمعنى، ثم وضح الفرق في دلالات أمثلة محددة."},{"n":9,"skill":"بناء وصف محسوس ومنظم","passage":"في نموذج من ضاديوم: «يتوسط المكتبة ممر واسع، وعلى جانبيه رفوف مرتبة، ويأتي ضوء العصر من نافذة عالية». يوضح الوصف المكان بعلاقات اتجاه ومشاهد حسية بدل تعداد صفات مبهمة، مع تسلسل من العام إلى الخاص.","prompt":"ما التفصيل الذي يبين اتجاه الرفوف؟","correct":"على جانبي الممر","w1":"ضوء العصر","w2":"النافذة العالية","w3":"المكتبة","practice":"اكتب وصفًا من ثماني جمل لمشهد طبيعي أو مكان مألوف، مع ثلاث علاقات مكانية وصورتين حسيتين."},{"n":10,"skill":"قراءة النادرة واستخراج المفارقة","passage":"نص «الولد سر أبيه» للجاحظ يحتاج المصدر الأصلي لتحديد الوقائع والمغزى. في نادرة أصلية قال متعلم: «قرأت عنوان الكتاب أمس، فأنا مستعد للامتحان كله!». تكمن المفارقة في المبالغة بالاستعداد اعتمادًا على قراءة عنوان فقط؛ لا تنسب النادرة للجاحظ.","prompt":"أين المفارقة في النادرة المستقلة؟","correct":"اعتبار قراءة العنوان استعدادًا كاملًا","w1":"وجود كتاب","w2":"الحديث مع صديق","w3":"اقتراب الامتحان","practice":"بعد قراءة نادرة الجاحظ الأصلية، استخرج عنصرًا فكاهيًا بشاهد موثق وقارن ببناء موقف من تأليفك."},{"n":11,"skill":"اسم المفعول ومعناه","passage":"«مكتوب» اسم مفعول من «كتب» على وزن «مفعول» يدل على ما وقع عليه فعل الكتابة، ويختلف عن «كاتب» اسم الفاعل. من غير الثلاثي يصاغ اسم المفعول بتغيير حرف المضارعة إلى ميم مضمومة وفتح ما قبل الآخر غالبًا مثل «مُستخرَج» من «استخرج».","prompt":"ما اسم المفعول من «كتب»؟","correct":"مكتوب","w1":"كاتب","w2":"كتابة","w3":"يكتب","practice":"اشتق ثمانية أسماء مفعول، واكتب أربع جمل تبرز الفرق بينها وبين أسماء الفاعل."},{"n":12,"skill":"المقامة والسرد والحيلة الأدبية","passage":"تحليل «المقامة البغدادية» لبديع الزمان الهمذاني يستلزم الرجوع إلى السرد الأصلي لمعرفة الراوي والشخصيات والمفارقة. قصة تدريبية مستقلة: دخل مسافر سوقًا غريبًا، فسأل عن المكان قبل شراء حاجته، ثم اكتشف أنه ترك نقوده في المنزل؛ الموقف ليس من المقامة.","prompt":"ما سبب تعذر شراء المسافر لحاجته؟","correct":"ترك النقود في المنزل","w1":"وجود سوق","w2":"سؤاله عن المكان","w3":"دخوله المدينة","practice":"اقرأ المقامة المدرسية وحدد الراوي ومثالًا لغويًا على الطرافة بشاهد صحيح، ثم اكتب نادرة سردية أصلية."},{"n":13,"skill":"صيغ المبالغة وشروط السياق","passage":"«غفّار» و«صبور» من صيغ المبالغة الشائعة على وزني «فعّال» و«فعول» على التوالي، وتختلف عن صيغة اسم الفاعل العادية في دلالة الكثرة أو قوة الصفة بحسب السياق. لا تعني الصيغة وحدها حكمًا قطعيًا على شخص معين.","prompt":"أي كلمة على وزن «فعول»؟","correct":"صبور","w1":"غفّار","w2":"كاتب","w3":"مكتوب","practice":"كوّن قائمة لخمسة أوزان مشهورة لصيغ المبالغة مع مثال أصيل لكل وزن وجملة توضح معناه."},{"n":14,"skill":"القصة القصيرة دون حكاية غير موثقة","passage":"لا يمكن تلخيص «تحت سماء المدينة» لمحمد عبد الملك من العنوان فقط؛ فالشخصيات والأحداث والرموز تتطلب النص الأصلي. في قصة مستقلة وجد طفل رسالة في حقيبته تدعوه إلى لقاء النادي الأدبي، فتردد ثم حضر مع صديقه، واكتشف قيمة مشاركة القصص.","prompt":"ما الحدث الذي دفع الطفل إلى حضور النادي؟","correct":"عثوره على رسالة الدعوة","w1":"شراء حقيبة","w2":"تأخر الصديق","w3":"غياب النادي","practice":"حدد عقدة وحلًا من القصة المدرسية بعد قراءتها مع شاهد، ثم اكتب قصة من إنشائك تحترم وحدة الحدث."},{"n":15,"skill":"دمج السرد والوصف بوعي","passage":"في قصة أصلية تأخر طلاب عن بداية معرض المدرسة بسبب المطر. وصف الراوي الأرصفة المبللة والهواء البارد ثم سرد كيف ساعد المتطوعون الزوار على الدخول بأمان. الوصف يخدم جو الحدث ولا يوقف الحكاية دون غرض.","prompt":"لماذا ورد وصف المطر في القصة؟","correct":"لتوضيح ظروف التأخر وجو الحدث","w1":"لحذف العقدة","w2":"لإلغاء الشخصيات","w3":"لذكر عنوان فقط","practice":"اكتب قصة من 150 كلمة تتضمن فقرة وصفية تخدم الحدث وحوارًا قصيرًا وحلًا مقنعًا."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='31c82c79-72de-4e4b-a5dc-6f9e598b3533'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 102 — من فنون الأدب' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G10_T2_ARAB102_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_UNIFIED_G10_T2_ARAB102_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G10_T2_ARAB102_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_UNIFIED_G10_T2_ARAB102_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;